import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  PieChart,
  Pie,
  Cell,
  Legend,
  ResponsiveContainer
} from "recharts";
import Header from "../../components/Header/Header";
import Footer from "../../components/Footer/Footer";
import "./completionpage.css";

interface Evaluation {
  question: string;
  difficulty: string;
  subject: string;
  subtopic: string;
  reference_answer: string;
  user_answer: string;
  explanation: string;
  grammar_score: number;
  cosine_similarity_score: number;
  keyword_score: number;
  llm_relevance_score: number;
  total_score: number;
  time_taken: number;
}

interface ChartData {
  subject?: string;
  total_score?: number;
  name?: string;
  value?: number;
}

const COLORS = ["#0088FE", "#00C49F", "#FFBB28", "#FF8042"];

const CompletionPage: React.FC = () => {
  const [evaluations, setEvaluations] = useState<Evaluation[]>([]);
  const [finalScore, setFinalScore] = useState<number>(0);
  const [message, setMessage] = useState<string>("");
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [totalTimeTaken, setTotalTimeTaken] = useState<number>(0);
  const [subjectPerformance, setSubjectPerformance] = useState<ChartData[]>([]);
  const [difficultyDistribution, setDifficultyDistribution] = useState<ChartData[]>([]);
  const [difficultyPerformance, setDifficultyPerformance] = useState<ChartData[]>([]);
  const { testid: paramTestId } = useParams();

  useEffect(() => {
    const fetchCompletionData = async () => {
      const storedTestId = localStorage.getItem("test_id");
      const testid = paramTestId || storedTestId;
      
      if (!testid) {
        setError("Test ID not found. Please try again.");
        setLoading(false);
        return;
      }

      try {
        setLoading(true);
        const response = await fetch("http://localhost:5000/view_result", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ testid }),
        });

        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }

        const data = await response.json();
        
        // Type-safe data parsing
        const parseNumber = (value: any, fallback = 0): number => {
          const num = Number(value);
          return isNaN(num) ? fallback : num;
        };

        setEvaluations(Array.isArray(data.evaluations) ? data.evaluations : []);
        setFinalScore(parseNumber(data.final_score));
        setMessage(data.message || "No feedback available");
        setTotalTimeTaken(parseNumber(data.total_time_taken));
        
        setSubjectPerformance(
          Array.isArray(data.subject_performance) 
            ? data.subject_performance.map((item: any) => ({
                subject: String(item.subject || "Unknown"),
                total_score: parseNumber(item.total_score)
              }))
            : []
        );
        
        setDifficultyDistribution(
          Array.isArray(data.difficulty_distribution)
            ? data.difficulty_distribution.map((item: any) => ({
                name: String(item.name || "Unknown"),
                value: parseNumber(item.value)
              }))
            : []
        );
        
        setDifficultyPerformance(
          Array.isArray(data.difficulty_performance)
            ? data.difficulty_performance.map((item: any) => ({
                name: String(item.name || "Unknown"),
                value: parseNumber(item.value)
              }))
            : []
        );

      } catch (err) {
        setError(err instanceof Error ? err.message : "Failed to load completion data");
      } finally {
        setLoading(false);
      }
    };

    fetchCompletionData();
  }, [paramTestId]);

  const formatOverallFeedback = (feedback: string) => {
    if (!feedback) return null;
    
    return feedback.split("**").map((section, index) => {
      const trimmed = section.trim();
      if (!trimmed) return null;
      
      return (
        <div key={index} className="feedback-section">
          <h4>{trimmed}</h4>
          {index % 2 === 0 && (
            <p>{feedback.split("**")[index + 1]?.trim()}</p>
          )}
        </div>
      );
    });
  };

  const getSubjectColor = (subject: string): string => {
    const colors: Record<string, string> = {
      "Computer Networks": "#8884d8",
      "Data Structures": "#82ca9d",
      "Operating Systems": "#ffc658",
      "Database Systems": "#ff8042",
      "Object Oriented Programming": "#0088FE"
    };
    return colors[subject] || `#${Math.floor(Math.random()*16777215).toString(16).padStart(6, '0')}`;
  };

  if (loading) {
    return (
      <div className="App">
        <Header />
        <div className="loading-container">
          <div className="loading-spinner"></div>
          <p>Loading your test results...</p>
        </div>
        <Footer />
      </div>
    );
  }

  if (error) {
    return (
      <div className="App">
        <Header />
        <div className="error-container">
          <h2>Error Loading Results</h2>
          <p>{error}</p>
          <button 
            className="retry-button"
            onClick={() => window.location.reload()}
          >
            Try Again
          </button>
        </div>
        <Footer />
      </div>
    );
  }

  return (
    <div className="App">
      <Header />
      <div className="cmain-content two-column-layout">
        <div className="charts-column">
          <h2>Performance Analysis</h2>
          
          {/* Subject Performance Chart */}
          <div className="chart-container">
            <h3>Subject Performance</h3>
            {subjectPerformance.length > 0 ? (
              <ResponsiveContainer width="100%" height={300}>
                <BarChart data={subjectPerformance}>
                  <XAxis dataKey="subject" />
                  <YAxis domain={[0, 100]} />
                  <Tooltip 
                    formatter={(value) => [`${value}%`, "Score"]}
                    labelFormatter={(label) => `Subject: ${label}`}
                  />
                  <Bar dataKey="total_score" name="Score">
                    {subjectPerformance.map((entry, index) => (
                      <Cell 
                        key={`subject-cell-${index}`} 
                        fill={getSubjectColor(entry.subject || "Unknown")} 
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            ) : (
              <div className="no-chart-data">
                <p>No subject performance data available</p>
              </div>
            )}
          </div>

          {/* Difficulty Distribution Chart */}
          <div className="chart-container">
            <h3>Difficulty Distribution</h3>
            {difficultyDistribution.length > 0 ? (
              <ResponsiveContainer width="100%" height={300}>
                <PieChart>
                  <Pie
                    data={difficultyDistribution}
                    cx="50%"
                    cy="50%"
                    outerRadius={80}
                    dataKey="value"
                    nameKey="name"
                    label={({ name, percent }) => `${name}: ${(percent * 100).toFixed(0)}%`}
                  >
                    {difficultyDistribution.map((entry, index) => (
                      <Cell 
                        key={`difficulty-cell-${index}`} 
                        fill={COLORS[index % COLORS.length]} 
                      />
                    ))}
                  </Pie>
                  <Tooltip 
                    formatter={(value, name) => [`${value} questions`, name]}
                  />
                  <Legend />
                </PieChart>
              </ResponsiveContainer>
            ) : (
              <div className="no-chart-data">
                <p>No difficulty distribution data available</p>
              </div>
            )}
          </div>

          {/* Difficulty Performance Chart */}
          <div className="chart-container">
            <h3>Performance by Difficulty</h3>
            {difficultyPerformance.length > 0 ? (
              <ResponsiveContainer width="100%" height={300}>
                <BarChart data={difficultyPerformance}>
                  <XAxis dataKey="name" />
                  <YAxis domain={[0, 100]} />
                  <Tooltip 
                    formatter={(value) => [`${value}%`, "Average Score"]}
                    labelFormatter={(label) => `Difficulty: ${label}`}
                  />
                  <Bar dataKey="value" name="Score">
                    {difficultyPerformance.map((entry, index) => (
                      <Cell 
                        key={`performance-cell-${index}`} 
                        fill={COLORS[index % COLORS.length]} 
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            ) : (
              <div className="no-chart-data">
                <p>No difficulty performance data available</p>
              </div>
            )}
          </div>
        </div>

        <div className="evaluations-column">
          <div className="overall-feedback">
            <h2>Test Results</h2>
            <div className="score-display">
              <h3>Overall Score: {finalScore.toFixed(2)}%</h3>
              <h4>Total Time Taken: {totalTimeTaken.toFixed(2)} minutes</h4>
            </div>
            {message && (
              <div className="feedback-container">
                <h4>Overall Feedback:</h4>
                {formatOverallFeedback(message)}
              </div>
            )}
          </div>

          {evaluations.length > 0 ? (
            evaluations.map((evaluation, index) => (
              <div key={`eval-${index}`} className="evaluation">
                <div className="question-header">
                  <span 
                    className="subject" 
                    style={{ backgroundColor: getSubjectColor(evaluation.subject) }}
                  >
                    {evaluation.subject || "Unknown Subject"}
                  </span>
                  <span 
                    className="difficulty" 
                    style={{
                      backgroundColor:
                        evaluation.difficulty?.toLowerCase() === "easy" ? "green" :
                        evaluation.difficulty?.toLowerCase() === "hard" ? "red" : "orange"
                    }}
                  >
                    {evaluation.difficulty || "Unknown"}
                  </span>
                </div>
                
                <h4>Question {index + 1}: {evaluation.question || "No question text"}</h4>
                
                <div className="answer-section">
                  <div className="user-answer">
                    <h5>Your Answer:</h5>
                    <p>{evaluation.user_answer || "No answer provided"}</p>
                  </div>
                  {evaluation.reference_answer && (
                    <div className="reference-answer">
                      <h5>Reference Answer:</h5>
                      <p>{evaluation.reference_answer}</p>
                    </div>
                  )}
                </div>
                
                <div className="scores-grid">
                  {[
                    { label: "Grammar", value: evaluation.grammar_score.toFixed(2) },
                    { label: "Relevance", value: evaluation.llm_relevance_score.toFixed(2) },
                    { label: "Keywords", value: evaluation.keyword_score.toFixed(2) },
                    { label: "Similarity", value: evaluation.cosine_similarity_score.toFixed(2) },
                    { label: "Total", value: evaluation.total_score.toFixed(2), isTotal: true },
                    { label: "Time", value: `${evaluation.time_taken.toFixed(2)} min` }
                  ].map((score, i) => (
                    <div 
                      key={`score-${index}-${i}`} 
                      className={`score-item ${score.isTotal ? 'total' : ''}`}
                    >
                      <span>{score.label}</span>
                      <span>{score.value}</span>
                    </div>
                  ))}
                </div>
                
                {evaluation.explanation && (
                  <div className="explanation">
                    <h5>Feedback:</h5>
                    <p>{evaluation.explanation}</p>
                  </div>
                )}
                <hr />
              </div>
            ))
          ) : (
            <div className="no-results">
              <p>No evaluation results available for this test.</p>
            </div>
          )}
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default CompletionPage;
